ALTER TABLE memberships ADD COLUMN custom_role_id uuid;
CREATE TABLE roles(org_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL DEFAULT gen_random_uuid(),name text NOT NULL,permissions text[] NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,name));
ALTER TABLE memberships ADD FOREIGN KEY(org_id,custom_role_id) REFERENCES roles(org_id,id);
CREATE TABLE invitations(org_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL DEFAULT gen_random_uuid(),email text NOT NULL,role text NOT NULL CHECK(role IN ('admin','member')),digest text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,accepted_at timestamptz,PRIMARY KEY(org_id,id));
CREATE UNIQUE INDEX invitation_pending ON invitations(org_id,email) WHERE accepted_at IS NULL;
CREATE TABLE workspace_teams(org_id uuid NOT NULL,workspace_id uuid NOT NULL,team_id uuid NOT NULL,PRIMARY KEY(org_id,workspace_id,team_id),FOREIGN KEY(org_id,workspace_id) REFERENCES workspaces(org_id,id) ON DELETE CASCADE,FOREIGN KEY(org_id,team_id) REFERENCES teams(org_id,id) ON DELETE CASCADE);
CREATE TABLE plans(id text PRIMARY KEY,limits jsonb NOT NULL);
INSERT INTO plans VALUES ('free','{"users":5,"workspaces":3,"requests":10000,"storage":1073741824,"jobs":1000,"bandwidth":10737418240}'),('pro','{"users":50,"workspaces":25,"requests":500000,"storage":53687091200,"jobs":100000,"bandwidth":536870912000}');
ALTER TABLE organizations ADD FOREIGN KEY(plan) REFERENCES plans(id);
ALTER TABLE organizations ADD COLUMN subscription_started_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE organizations ADD COLUMN subscription_version bigint NOT NULL DEFAULT 0;
ALTER TABLE organizations ADD CONSTRAINT subscription_states CHECK(subscription_status IN ('TRIAL','ACTIVE','PAST_DUE','CANCELLED','SUSPENDED'));
CREATE TABLE usage_events(org_id uuid NOT NULL REFERENCES organizations(id),id text NOT NULL,metric text NOT NULL,quantity bigint NOT NULL CHECK(quantity>0),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id));
CREATE TABLE platform_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES users(id),event text NOT NULL,request_id text NOT NULL,ip text,result text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER platform_audit_append_only BEFORE UPDATE OR DELETE ON platform_audit FOR EACH ROW EXECUTE FUNCTION deny_audit_change();
CREATE TABLE platform_config(key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE webhook_deliveries ADD COLUMN http_status int;
ALTER TABLE webhook_deliveries ADD COLUMN last_error text;
ALTER TABLE webhook_deliveries ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE webhook_deliveries ADD COLUMN completed_at timestamptz;
ALTER TABLE webhooks ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE api_keys ADD COLUMN created_by uuid REFERENCES users(id);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['roles','invitations','workspace_teams','usage_events'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant ON %I USING (org_id = nullif(current_setting(''app.org_id'',true),'''')::uuid) WITH CHECK (org_id = nullif(current_setting(''app.org_id'',true),'''')::uuid)',t);
END LOOP; END $$;
CREATE INDEX tokens_expiry ON tokens(expires_at);
CREATE INDEX notifications_user_time ON notifications(org_id,user_id,created_at DESC);
CREATE INDEX invitations_expiry ON invitations(expires_at);
CREATE TABLE schedule_runs(name text NOT NULL,period text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(name,period));
